def patch_bytes(data, offset, new_bytes):
    buf = bytearray(data)
    buf[offset:offset + len(new_bytes)] = new_bytes
    return bytes(buf)


def view_slice(data, start, end):
    mv = memoryview(data)
    return bytes(mv[start:end])


def find_pattern(data, pattern):
    offsets = []
    start = 0
    while True:
        pos = data.find(pattern, start)
        if pos == -1:
            break
        offsets.append(pos)
        start = pos + 1
    return offsets
